const request = $input.first().json;
const headers = request.headers ?? {};
const body = request.body ?? {};
const requiredHeaders = ['x-dta-workflow-id', 'x-dta-execution-id', 'idempotency-key', 'x-dta-run-id', 'x-dta-user-id', 'x-dta-actor-id'];
const missing = requiredHeaders.filter((name) => typeof headers[name] !== 'string' || !headers[name].trim());
if (missing.length) throw new Error(`Missing DTA scope headers: ${missing.join(', ')}`);
if (headers['x-dta-workflow-id'] !== 'meeting-pilot-readiness') throw new Error('Unexpected DTA workflow id');
if (body.schemaVersion !== '1.0') throw new Error('Unsupported DTA envelope version');
if (body.source?.runId !== headers['x-dta-run-id']) throw new Error('Run scope mismatch');
if (body.source?.userId !== headers['x-dta-user-id']) throw new Error('User scope mismatch');
if (body.execution?.id !== headers['x-dta-execution-id']) throw new Error('Execution scope mismatch');
if (body.execution?.idempotencyKey !== headers['idempotency-key']) throw new Error('Idempotency scope mismatch');
return [{ json: { ok: true, dtaProbe: true, workflowId: headers['x-dta-workflow-id'], runId: headers['x-dta-run-id'], executionId: headers['x-dta-execution-id'], idempotencyKey: headers['idempotency-key'] } }];
